<script setup>
import {sitePath} from './paths.js';

import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import {Activity,ArrowUpRight,ArrowDownRight,Building2,Car,ChevronDown,ChevronRight,CloudSun,Crosshair,Expand,Layers3,Leaf,MapPin,Maximize2,Minus,Pause,Play,Plus,Radio,RotateCcw,Settings2,ShieldCheck,Signal,Sun,Wifi,X,Zap,Check,Clock,Navigation} from 'lucide-vue-next';
import CityScene from './components/CityScene.vue';
import Chart from './components/Chart.vue';
import CityHeader from './components/CityHeader.vue';
import CityPanelDetail from './components/CityPanelDetail.vue';
const tabs=[{name:'城市总览',en:'CITY OVERVIEW',icon:Building2},{name:'智慧交通',en:'SMART MOBILITY',icon:Car},{name:'绿色能源',en:'GREEN ENERGY',icon:Zap},{name:'生态环境',en:'ECO ENVIRONMENT',icon:Leaf},{name:'公共安全',en:'PUBLIC SAFETY',icon:ShieldCheck}];
const active=ref(0),digital=ref(false),rotate=ref(false),traffic=ref(true),energy=ref(true),scan=ref(true),zoom=ref(0),layers=ref(false),paused=ref(false),time=ref(new Date()),range=ref('今日'),modal=ref(null),notice=ref(''),selectedDistrict=ref('全市'),districtOpen=ref(false),fullscreen=ref(false);let timer,toastTimer;
const profiles=[{score:'98.6',numbers:['2,487.1','12,846','98.62','36,892'],unit:['万人','万次','%','路'],names:['常住人口','今日数据交互','城市运行指数','在线感知设备']},{score:'96.8',numbers:['486.2','42.8','96.80','12,608'],unit:['万辆','km/h','%','个'],names:['今日在途车辆','路网平均速度','道路畅通率','智慧交通终端']},{score:'97.2',numbers:['8,624','32.6','97.20','1,286'],unit:['万kWh','%','%','座'],names:['今日能源供给','清洁能源占比','供能可靠指数','智慧能源站点']},{score:'99.1',numbers:['32','48.6','99.10','682'],unit:['AQI','%','%','处'],names:['全市空气质量','城区绿化覆盖','环境达标率','环境监测站点']},{score:'99.3',numbers:['128','99.3','3.2','8,620'],unit:['起','%','分钟','台'],names:['今日城市事件','安全运行指数','平均响应时间','在线安防设备']}];
const profile=computed(()=>profiles[active.value]);
const clock=computed(()=>time.value.toLocaleTimeString('zh-CN',{hour12:false}));const date=computed(()=>`${time.value.getFullYear()}.${String(time.value.getMonth()+1).padStart(2,'0')}.${String(time.value.getDate()).padStart(2,'0')}`);
const events=ref([{id:'SH-20260904-0128',name:'陆家嘴环路交通流量预警',type:'交通运行',location:'浦东新区 · 陆家嘴环路',level:'关注',status:'处理中',time:'15:32:08',detail:'路段车辆密度高于同期均值 18%，已触发信号灯配时优化建议。当前通行秩序正常。',icon:Car},{id:'SH-20260904-0127',name:'黄浦滨江环境监测完成',type:'生态环境',location:'黄浦区 · 滨江步道',level:'常规',status:'已完成',time:'15:30:42',detail:'本轮水质、空气与噪声监测完成，全部指标处于正常范围。',icon:Leaf},{id:'SH-20260904-0126',name:'静安智慧路灯巡检完成',type:'公共设施',location:'静安区 · 南京西路',level:'常规',status:'已完成',time:'15:28:16',detail:'128 盏智慧路灯完成在线巡检，设备通信及照明状态正常。',icon:Zap}]);
const filteredEvents=computed(()=>events.value.filter(e=>active.value===0||active.value===4||e.type===['','交通运行','公共设施','生态环境'][active.value]));
const districtFactor=computed(()=>selectedDistrict.value==='全市'?1:.11+['浦东新区','黄浦区','徐汇区','静安区'].indexOf(selectedDistrict.value)*.016);
const metrics=computed(()=>profile.value.numbers.map((x,i)=>{if(i===2||selectedDistrict.value==='全市')return x;return (Number(x.replaceAll(',',''))*districtFactor.value).toLocaleString('en-US',{maximumFractionDigits:1})}));
function toast(s){notice.value=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.value='',3000)}
function switchTab(i){active.value=i;range.value='今日'}
function reset(){digital.value=false;rotate.value=false;zoom.value=0;selectedDistrict.value='全市';traffic.value=true;energy.value=true;scan.value=true;toast('已恢复城市总览视角')}
async function full(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('当前浏览器不支持全屏，请使用浏览器全屏快捷键')}}
function syncFull(){fullscreen.value=!!document.fullscreenElement}
function key(e){if(modal.value&&e.key==='Tab'){const items=[...document.querySelectorAll('.modal button:not([disabled]),.modal input')];const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||!items.includes(document.activeElement))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||!items.includes(document.activeElement))){e.preventDefault();first?.focus()}}if(e.key==='Escape'){modal.value=null;layers.value=false;districtOpen.value=false}}
onMounted(()=>{timer=setInterval(()=>{if(!paused.value)time.value=new Date()},1000);document.addEventListener('keydown',key);document.addEventListener('fullscreenchange',syncFull)});onBeforeUnmount(()=>{clearInterval(timer);clearTimeout(toastTimer);document.removeEventListener('keydown',key);document.removeEventListener('fullscreenchange',syncFull)});
</script>
<template>
<div class="dashboard" :class="{'panel-motion-paused':paused}">
<CityHeader :clock="clock" :date="date" :weekday="'星期'+'日一二三四五六'[time.getDay()]" :fullscreen="fullscreen" @fullscreen="full"/>
<nav class="navigation" aria-label="主题导航"><div class="system-state"><i class="status-dot"></i> 城市运行正常 <a class="studio-launch" :href="sitePath('/header-studio/')">Header 设计器 <span>↗</span></a></div><div class="tabs" role="tablist"><button v-for="(tab,i) in tabs" :key="tab.name" role="tab" :aria-selected="active===i" :class="{active:active===i}" @click="switchTab(i)"><component :is="tab.icon" :size="16"/>{{tab.name}}<span class="tab-mark"></span></button></div><div class="stream-state"><span class="live-dot"></span>{{paused?'数据更新已暂停':'数据实时同步'}} <Signal :size="15"/></div></nav>
<main class="main-grid">
  <aside class="side left-side">
    <section class="panel overview-panel"><CityPanelDetail/><div class="panel-heading"><h2><span></span>{{active===0?'城市运行概况':tabs[active].name+'概况'}}</h2><span class="micro">OVERVIEW</span></div><div class="score-row"><div class="score-orbit"><svg viewBox="0 0 126 126"><circle class="orbit-base" cx="63" cy="63" r="53"/><circle class="orbit-ticks" cx="63" cy="63" r="59"/><circle class="orbit-progress" cx="63" cy="63" r="53"/><circle cx="63" cy="63" r="43" fill="none" stroke="#17495a" stroke-dasharray="2 5"/></svg><div><strong>{{profile.score}}</strong><small>综合运行指数</small></div></div><div class="score-copy"><span class="state-tag"><i></i>运行优良</span><p>城市脉搏 · 实时感知</p><div>较昨日 <b>+0.8 <ArrowUpRight :size="13"/></b></div></div></div><div class="overview-stats"><div><span>接入系统</span><strong>{{186+active*12}}<small>个</small></strong></div><div><span>数据汇聚</span><strong>{{(28.64+active*1.7).toFixed(2)}}<small>亿条</small></strong></div><div><span>服务可用率</span><strong>99.98<small>%</small></strong></div></div></section>
    <section class="panel traffic-panel"><CityPanelDetail/><div class="panel-heading"><h2><span></span>{{active===2?'能源负荷趋势':active===3?'空气质量趋势':'城市交通态势'}}</h2><div class="mini-tabs"><button v-for="r in ['今日','本周']" :class="{selected:range===r}" @click="range=r">{{r}}</button></div></div><div class="traffic-stats"><div><span>{{range==='今日'?'实时':'周均'}}路网畅通率</span><strong>{{range==='今日'?'96.8':'94.6'}}<small>%</small><em>↑ 2.1%</em></strong></div><div><span>平均通行速度</span><strong>{{range==='今日'?'42.8':'40.2'}}<small>km/h</small></strong></div></div><div class="chart-legend"><span><i></i>{{range==='今日'?'今日流量':'本周均值'}}</span><span><i class="blue"></i>{{range==='今日'?'昨日同期':'上周均值'}}</span><small>单位：万辆</small></div><Chart :variant="active+(range==='本周'?3:0)"/><div class="panel-bottom-note"><span class="status-dot"></span>全市主干路通行平稳 <span>较昨日改善 <b>2.1%</b></span></div></section>
    <section class="panel energy-panel"><CityPanelDetail/><div class="panel-heading"><h2><span></span>城市能源监测</h2><span class="micro">ENERGY</span></div><div class="energy-summary"><div><span>今日综合用能</span><strong>{{active===2?'9,216':'8,624'}}<small>万 kWh</small></strong></div><span class="down"><ArrowDownRight :size="15"/> 3.6% <small>同比</small></span></div><div class="chart-legend"><span><i></i>用电量</span><span><i class="blue"></i>清洁能源</span><small>单位：万 kWh</small></div><Chart type="bar" :variant="active"/></section>
  </aside>
  <section class="center-column">
    <div class="metric-strip"><div v-for="(name,i) in profile.names" class="metric" :key="name"><span>{{name}}<component :is="[Building2,Activity,ShieldCheck,Radio][i]" :size="13"/></span><div><strong>{{metrics[i]}}</strong><small>{{profile.unit[i]}}</small></div><p><span>较昨日</span> <b>↑ {{['0.12','12.8','0.8','2.6'][i]}}%</b></p></div></div>
    <div class="map-area" :class="{'digital-mode':digital}"><div class="city-image"></div><div class="city-shade"></div><CityScene @unavailable="digital=false;toast('当前设备使用城市夜景模式')" :digital="digital" :rotate="rotate" :traffic="traffic" :energy="energy" :scan="scan" :zoom="zoom"/>
      <div class="map-topline"><div class="area-select"><button @click="districtOpen=!districtOpen"><MapPin :size="14"/>上海市 · {{selectedDistrict}}<ChevronDown :size="13"/></button><div v-if="districtOpen" class="district-menu"><button v-for="d in ['全市','浦东新区','黄浦区','徐汇区','静安区']" @click="selectedDistrict=d;districtOpen=false">{{d}}<Check v-if="d===selectedDistrict" :size="13"/></button></div></div><div class="scene-mode"><button :class="{on:!digital}" @click="digital=false">城市夜景</button><button :class="{on:digital}" @click="digital=true">数字孪生</button></div></div>
      <div class="map-caption"><span class="tiny-cross">+</span> SHANGHAI DIGITAL TWIN <small>31°14′ N &nbsp; 121°29′ E</small></div>
      <div class="landmark landmark-tower" v-if="energy&&!digital"><button @click="modal={landmark:true,name:'上海中心大厦',location:'浦东新区 · 银城中路 501 号',detail:'上海中心大厦，高 632 米，共 127 层。当前楼宇能源、消防与客流监测运行正常。',status:'运行正常'}"><i></i><span>上海中心大厦<small><b>●</b> 运行正常 <ChevronRight :size="10"/></small></span></button><div class="marker-stem"></div></div>
      <div class="landmark landmark-pearl" v-if="traffic&&!digital"><button @click="modal={landmark:true,name:'东方明珠',location:'浦东新区 · 世纪大道 1 号',detail:'东方明珠广播电视塔，高 468 米。当前区域客流平稳，设备运行正常。',status:'运行正常'}"><i></i><span>东方明珠<small><b>●</b> 设备在线</small></span></button><div class="marker-stem"></div></div>
      <div class="map-tools"><button :class="{on:layers}" title="图层控制" aria-label="图层控制" @click="layers=!layers"><Layers3 :size="18"/></button><span></span><button title="放大三维场景" aria-label="放大三维场景" @click="digital=true;zoom=Math.abs(zoom)+1"><Plus :size="18"/></button><button title="缩小三维场景" aria-label="缩小三维场景" @click="digital=true;zoom=-Math.abs(zoom)-1"><Minus :size="18"/></button><span></span><button title="重置视角" aria-label="重置视角" @click="reset"><Crosshair :size="18"/></button></div>
      <div v-if="layers" class="layer-panel"><strong>场景图层 <button class="icon-btn" @click="layers=false" aria-label="关闭图层"><X :size="14"/></button></strong><label v-for="item in [{name:'交通路网',key:'traffic'},{name:'智慧楼宇',key:'energy'},{name:'城市扫描',key:'scan'}]" :key="item.key"><span>{{item.name}}</span><input type="checkbox" :checked="item.key==='traffic'?traffic:item.key==='energy'?energy:scan" @change="item.key==='traffic'?traffic=!traffic:item.key==='energy'?energy=!energy:scan=!scan"/></label></div>
      <div class="compass"><Navigation :size="24"/><span>N</span><i></i></div><div class="map-legend"><span><i></i>感知设备</span><span><i></i>能源节点</span><span><i></i>城市路网</span></div>
      <div class="map-bottom"><div><span class="live-dot"></span>{{digital?'三维数字孪生场景':'陆家嘴核心区'}} <small>{{digital?'拖动旋转 · 滚轮缩放':'城市实景 · 夜间模式'}}</small></div><button :class="{on:rotate}" @click="digital=true;rotate=!rotate"><component :is="rotate?Pause:Play" :size="13"/>{{rotate?'暂停漫游':'自动漫游'}}</button></div>
    </div>
    <section class="panel events-panel"><CityPanelDetail/><div class="panel-heading"><h2><span></span>城市实时动态 <em>LIVE</em></h2><button class="text-button" @click="modal={all:true,name:'城市事件中心'}">全部事件 <ChevronRight :size="13"/></button></div><div class="event-head"><span>事件信息</span><span>状态</span><span>更新时间</span></div><button class="event-row" v-for="event in filteredEvents" :key="event.id" @click="modal=event"><span class="event-name"><component :is="event.icon" :size="15"/><span>{{event.name}}</span></span><span class="event-status" :class="{warning:event.status==='处理中'}">{{event.status}}</span><time>{{event.time}}</time></button><div v-if="!filteredEvents.length" class="empty-state">当前暂无待处理事件</div></section>
  </section>
  <aside class="side right-side">
    <section class="panel environment-panel"><CityPanelDetail/><div class="panel-heading"><h2><span></span>生态环境质量</h2><span class="micro">ENVIRONMENT</span></div><div class="aqi-row"><div class="aqi-number"><span>空气质量指数 AQI</span><strong>32 <em>优</em></strong><p>空气清新，适宜户外活动</p></div><div class="air-symbol"><Leaf :size="35"/><i></i><i></i></div></div><div class="pollutants"><div><span>PM2.5</span><strong>12<small>μg/m³</small></strong></div><div><span>PM10</span><strong>28<small>μg/m³</small></strong></div><div><span>O₃</span><strong>86<small>μg/m³</small></strong></div></div><Chart type="radar"/></section>
    <section class="panel device-panel"><CityPanelDetail/><div class="panel-heading"><h2><span></span>城市感知网络</h2><span class="micro">IOT NETWORK</span></div><div class="device-main"><div class="donut"><svg viewBox="0 0 110 110"><circle cx="55" cy="55" r="43" fill="none" stroke="#143344" stroke-width="9"/><circle cx="55" cy="55" r="43" fill="none" stroke="#22cbd4" stroke-width="9" stroke-dasharray="195 270" transform="rotate(-90 55 55)"/><circle cx="55" cy="55" r="43" fill="none" stroke="#3182d3" stroke-width="9" stroke-dasharray="61 270" stroke-dashoffset="-199" transform="rotate(-90 55 55)"/></svg><div><strong>99.2<small>%</small></strong><span>设备在线率</span></div></div><div class="device-totals"><span>接入设备总数</span><strong>36,892<small>台</small></strong><p><i></i>在线 <b>36,597</b></p><p><i></i>离线 <b>295</b></p></div></div><div class="device-bars"><div v-for="(d,i) in [{name:'视频感知',value:'16,428',p:88},{name:'环境传感',value:'8,642',p:57},{name:'智慧设施',value:'11,822',p:72}]"><span>{{d.name}}</span><div><i :style="{width:d.p+'%'}" :class="'bar-'+i"></i></div><b>{{d.value}}</b></div></div></section>
    <section class="panel safety-panel"><CityPanelDetail/><div class="panel-heading"><h2><span></span>公共安全保障</h2><span class="micro">PUBLIC SAFETY</span></div><div class="safety-score"><div class="shield"><ShieldCheck :size="35"/></div><div><span>城市安全运行天数</span><strong>365<small>天</small></strong></div><span class="state-tag">平稳</span></div><div class="safety-stats"><div><span>今日处置事件</span><strong>128<small>起</small></strong></div><div><span>事件办结率</span><strong>99.3<small>%</small></strong></div><div><span>平均响应</span><strong>3.2<small>min</small></strong></div></div><div class="safety-note"><ShieldCheck :size="13"/>全市安全态势平稳可控<ChevronRight :size="13"/></div></section>
  </aside>
</main>
<footer><div><span class="status-dot"></span>平台运行正常<span class="footer-divider">|</span><span>数据接入 <b>186</b> 个系统</span><span class="footer-divider">|</span><span>数据延迟 <b>23</b> ms</span></div><nav class="footer-center demo-links" aria-label="切换大屏"><a :href="sitePath('/')" aria-current="page">智慧城市</a><a :href="sitePath('/demo01')">智慧农业 ↗</a><a :href="sitePath('/demo02')">智慧工业 ↗</a><a :href="sitePath('/demo03/')">智慧园区 ↗</a></nav><div><span class="demo-tag">演示数据</span><span>更新于 {{clock}}</span><button class="icon-btn" :aria-label="paused?'恢复实时更新':'暂停实时更新'" @click="paused=!paused"><component :is="paused?Play:Pause" :size="12"/></button><Wifi :size="13"/></div></footer>
<Transition name="toast"><div v-if="notice" class="toast-message"><Check :size="16"/>{{notice}}</div></Transition>
<div v-if="modal" class="modal-backdrop" @click.self="modal=null"><section class="modal" role="dialog" aria-modal="true" :aria-label="modal.name"><div class="modal-heading"><span><Activity :size="18"/>{{modal.name}}</span><button class="icon-btn" @click="modal=null" aria-label="关闭详情" autofocus><X :size="19"/></button></div><template v-if="modal.all"><p class="modal-subtitle">上海市城市运行事件 · {{date}}</p><button class="modal-event" v-for="e in events" @click="modal=e"><component :is="e.icon" :size="20"/><span><strong>{{e.name}}</strong><small>{{e.location}} · {{e.time}}</small></span><span class="event-status" :class="{warning:e.status==='处理中'}">{{e.status}}</span><ChevronRight :size="16"/></button></template><template v-else><span class="state-tag">{{modal.status}}</span><p class="detail-location"><MapPin :size="15"/>{{modal.location}}</p><p class="detail-copy">{{modal.detail}}</p><div class="detail-meta"><span>{{modal.landmark?'监测状态':'事件编号'}}</span><strong>{{modal.id||'楼宇、能源、消防监测全部在线'}}</strong></div><div class="detail-meta"><span>数据来源</span><strong>城市运行模拟数据</strong></div><button v-if="modal.status==='处理中'" class="primary-button" @click="modal.status='已完成';modal.detail='本次模拟事件已确认处置完成，路段交通运行恢复正常。';toast('事件已确认处置完成')"><Check :size="16"/>确认处置完成</button><button v-else class="primary-button" @click="modal=null">返回运行中心</button></template></section></div>
</div>
</template>
